SELECT DISTINCT city
FROM   customers
ORDER BY city ASC;

-- WRONG: never matches
SELECT * FROM employees WHERE bonus = NULL;

-- RIGHT
SELECT * FROM employees WHERE bonus IS NOT NULL;

-- names starting with 'An', ending with 'a'
SELECT * FROM users
WHERE  name LIKE  'An%';

-- exactly five-character codes
SELECT * FROM products
WHERE  sku LIKE  '____';

-- scalar: one value
SELECT name FROM users
WHERE  id = (SELECT MAX(user_id) FROM users);

-- list: many values
SELECT * FROM orders
WHERE  customer_id IN (SELECT id FROM customers WHERE vip = 1);

-- derived table: use it like a table
SELECT t.year, AVG(t.revenue)
FROM   (SELECT YEAR(o.date) AS year, o.amount AS revenue FROM orders o) t
GROUP BY t.year;

-- customers who have placed an order
SELECT c.name FROM customers c
WHERE EXISTS (
  SELECT 1 FROM orders o
  WHERE o.customer_id = c.id
);

WITH vip_users AS (
  SELECT id FROM users WHERE tier = 'vip'
),
orders AS (
  SELECT * FROM orders WHERE user_id IN (SELECT id FROM vip_users)
)
SELECT user_id, SUM(amount) FROM orders
GROUP BY user_id;

WITH RECURSIVE countdown AS (
  SELECT 5 AS n
  UNION ALL
  SELECT n - 1 FROM countdown WHERE n > 1
)
SELECT n FROM countdown;

BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;   -- or ROLLBACK; if anything went wrong

CREATE TABLE employees (
  id         INT PRIMARY KEY,
  email      VARCHAR(255) UNIQUE NOT NULL,
  dept_id    INT REFERENCES departments(id),
  CHECK (salary >= 0)
);
